// shared/utils/ObjectPool.js
export class ObjectPool {
    constructor(createFn, resetFn, initialSize = 100) {
        this.createFn = createFn;
        this.resetFn = resetFn;
        this.pool = [];
        for (let i = 0; i < initialSize; i++) {
            this.pool.push(this.createFn());
        }
        this.activeCount = 0;
    }

    acquire() {
        let item = this.pool.length > 0 ? this.pool.pop() : this.createFn();
        this.activeCount++;
        return item;
    }

    release(item) {
        if (this.resetFn) {
            this.resetFn(item);
        }
        this.pool.push(item);
        this.activeCount--;
        if (this.activeCount < 0) this.activeCount = 0;
    }

    getActiveCount() {
        return this.activeCount;
    }

    getTotalSize() {
        return this.pool.length + this.activeCount;
    }
}
