// shared/physics/PhysicsEngine.js
import * as THREE from 'three';
import { MathUtils } from '../utils/MathUtils.js';

export class PhysicsEngine {
    static checkAABBCollision(mesh1, mesh2) {
        if (!mesh1.geometry || !mesh2.geometry) return false;

        // Ensure bounding boxes are up to date
        mesh1.updateMatrixWorld();
        mesh2.updateMatrixWorld();

        const box1 = new THREE.Box3().setFromObject(mesh1);
        const box2 = new THREE.Box3().setFromObject(mesh2);

        return MathUtils.checkAABB(box1, box2);
    }

    static getVelocityDistance(velocity, deltaTime) {
        const speed = velocity.length();
        return speed * deltaTime;
    }
}
