// shared/vfx/ParticleManager.js
import * as THREE from 'three';
import { ObjectPool } from '../utils/ObjectPool.js';

class Particle {
    constructor() {
        this.mesh = null;
        this.position = new THREE.Vector3();
        this.velocity = new THREE.Vector3();
        this.life = 0;
        this.maxLife = 1.0;
        this.active = false;
    }

    initialize(scene, color) {
        const geometry = new THREE.SphereGeometry(0.05, 8, 8);
        const material = new THREE.MeshStandardMaterial({ 
            color: color,
            emissive: color,
            emissiveIntensity: 2,
            transparent: true,
            opacity: 1
        });
        this.mesh = new THREE.Mesh(geometry, material);
        scene.add(this.mesh);

        this.position.set(0, 0, 0);
        this.velocity.set(0, 0, 0);
        this.life = 0;
        this.maxLife = 1.0;
        this.active = false;
    }

    reset(position, velocity, life, color) {
        this.position.copy(position);
        this.velocity.copy(velocity);
        this.life = life;
        this.maxLife = life;
        this.active = true;

        if (this.mesh.material.color) {
            this.mesh.material.color.set(color);
        }
        if (this.mesh.material.emissive) {
            this.mesh.material.emissive.set(color);
        }
        this.mesh.position.copy(this.position);
        this.mesh.visible = true;
    }

    update(deltaTime) {
        if (!this.active) return;

        this.life -= deltaTime;
        if (this.life <= 0) {
            this.active = false;
            this.mesh.visible = false;
            return;
        }

        // Update position with velocity
        this.position.addScaledVector(this.velocity, deltaTime);

        // Apply gravity/drag
        this.velocity.y -= 9.8 * deltaTime * 0.5; // Gravity
        this.velocity.multiplyScalar(0.98); // Drag

        this.mesh.position.copy(this.position);

        // Fade out based on life
        const opacity = Math.max(0, this.life / this.maxLife);
        this.mesh.material.opacity = opacity;
        this.mesh.material.emissiveIntensity = 2 * opacity;
    }

    dispose() {
        if (this.mesh) {
            if (this.mesh.parent) {
                this.mesh.parent.remove(this.mesh);
            }
            this.mesh.geometry.dispose();
            this.mesh.material.dispose();
            this.mesh = null;
        }
    }
}

export class ParticleManager {
    constructor(scene) {
        this.scene = scene;
        this.particles = [];
        this.maxParticles = 500;

        // Initialize particle pool
        for (let i = 0; i < this.maxParticles; i++) {
            const particle = new Particle();
            particle.initialize(this.scene, 0x00ffff);
            this.particles.push(particle);
        }
    }

    spawnBurst(position, color, count = 20, speedRange = [2, 5]) {
        let spawnedCount = 0;

        for (let i = 0; i < this.particles.length && spawnedCount < count; i++) {
            const particle = this.particles[i];
            if (!particle.active) {
                // Random spherical coordinates
                const theta = Math.random() * Math.PI * 2;
                const phi = Math.acos(2 * Math.random() - 1);
                const speed = Math.random() * (speedRange[1] - speedRange[0]) + speedRange[0];

                const vx = Math.sin(phi) * Math.cos(theta) * speed;
                const vy = Math.sin(phi) * Math.sin(theta) * speed;
                const vz = Math.cos(phi) * speed;

                const velocity = new THREE.Vector3(vx, vy, vz);
                const life = Math.random() * 0.5 + 0.5; // 0.5 to 1.0 seconds

                particle.reset(position, velocity, life, color);
                spawnedCount++;
            }
        }
    }

    update(deltaTime) {
        for (let particle of this.particles) {
            if (particle.active) {
                particle.update(deltaTime);
            }
        }
    }

    dispose() {
        for (let particle of this.particles) {
            particle.dispose();
        }
        this.particles = [];
    }
}
