// shared/vfx/HitStop.js
export class HitStop {
    constructor() {
        this.isStopped = false;
        this.stopFrames = 0;
        this.maxStopFrames = 3; // Freeze for 3 frames
    }

    trigger(frames = 3) {
        this.isStopped = true;
        this.stopFrames = frames;
    }

    update() {
        if (this.isStopped) {
            this.stopFrames--;
            if (this.stopFrames <= 0) {
                this.isStopped = false;
                this.stopFrames = 0;
            }
            return true; // Still stopping
        }
        return false; // Not stopping
    }

    isCurrentlyStopping() {
        return this.isStopped;
    }
}
