// shared/vfx/MotionTrail.js
import * as THREE from 'three';

export class MotionTrail {
    constructor(scene, maxHistory = 20) {
        this.scene = scene;
        this.maxHistory = maxHistory;
        this.trails = new Map(); // Map of trailId -> { history: [], mesh: null }
    }

    addTrail(entityId, position, velocity, color, length = 10) {
        if (!this.trails.has(entityId)) {
            const geometry = new THREE.CylinderGeometry(0.05, 0.02, 1, 8);
            geometry.rotateX(Math.PI / 2); // Align along Z axis

            const material = new THREE.MeshStandardMaterial({
                color: color,
                emissive: color,
                emissiveIntensity: 1,
                transparent: true,
                opacity: 0.5,
                depthWrite: false
            });

            const mesh = new THREE.Mesh(geometry, material);
            this.scene.add(mesh);

            this.trails.set(entityId, {
                history: [],
                mesh: mesh,
                color: color,
                length: length
            });
        }

        const trail = this.trails.get(entityId);
        trail.history.push({
            position: position.clone(),
            velocity: velocity.clone(),
            timestamp: performance.now()
        });

        if (trail.history.length > this.maxHistory) {
            trail.history.shift();
        }

        this.updateTrailMesh(entityId);
    }

    updateTrailMesh(entityId) {
        const trail = this.trails.get(entityId);
        if (!trail || trail.history.length < 2) return;

        // Update mesh position and scale based on history
        const firstPos = trail.history[0].position;
        const lastPos = trail.history[trail.history.length - 1].position;

        const direction = new THREE.Vector3().subVectors(lastPos, firstPos);
        const distance = direction.length();

        if (distance > 0.1) {
            trail.mesh.position.copy(firstPos);
            trail.mesh.scale.set(1, 1, Math.max(distance, 0.5));

            // Look at the last position
            trail.mesh.lookAt(lastPos.x, lastPos.y, lastPos.z);

            // Update opacity based on history age
            const ageRatio = trail.history.length / this.maxHistory;
            trail.mesh.material.opacity = 0.6 * (1 - ageRatio) + 0.2;
        }
    }

    removeTrail(entityId) {
        if (this.trails.has(entityId)) {
            const trail = this.trails.get(entityId);
            if (trail.mesh.parent) {
                trail.mesh.parent.remove(trail.mesh);
            }
            trail.mesh.geometry.dispose();
            trail.mesh.material.dispose();
            this.trails.delete(entityId);
        }
    }

    clearAll() {
        for (let entityId of this.trails.keys()) {
            this.removeTrail(entityId);
        }
    }

    dispose() {
        this.clearAll();
    }
}
