import * as THREE from 'three';

export class ProceduralAssets {
    static createStarfieldTexture() {
        const canvas = document.createElement('canvas');
        canvas.width = 256;
        canvas.height = 256;
        const ctx = canvas.getContext('2d');

        // Background
        ctx.fillStyle = '#050510';
        ctx.fillRect(0, 0, 256, 256);

        // Stars
        for (let i = 0; i < 200; i++) {
            const x = Math.random() * 256;
            const y = Math.random() * 256;
            const radius = Math.random() * 1.5 + 0.5;
            const opacity = Math.random() * 0.8 + 0.2;

            ctx.beginPath();
            ctx.arc(x, y, radius, 0, Math.PI * 2);
            ctx.fillStyle = `rgba(255, 255, 255, ${opacity})`;
            ctx.fill();
        }

        const texture = new THREE.CanvasTexture(canvas);
        return texture;
    }

    static createNeonGridTexture() {
        const canvas = document.createElement('canvas');
        canvas.width = 512;
        canvas.height = 512;
        const ctx = canvas.getContext('2d');

        // Background
        ctx.fillStyle = '#0a0a1a';
        ctx.fillRect(0, 0, 512, 512);

        // Grid lines
        ctx.strokeStyle = 'rgba(0, 255, 255, 0.3)';
        ctx.lineWidth = 2;

        const gridSize = 64;
        for (let x = 0; x <= 512; x += gridSize) {
            ctx.beginPath();
            ctx.moveTo(x, 0);
            ctx.lineTo(x, 512);
            ctx.stroke();
        }

        for (let y = 0; y <= 512; y += gridSize) {
            ctx.beginPath();
            ctx.moveTo(0, y);
            ctx.lineTo(512, y);
            ctx.stroke();
        }

        const texture = new THREE.CanvasTexture(canvas);
        texture.wrapS = THREE.RepeatWrapping;
        texture.wrapT = THREE.RepeatWrapping;
        texture.repeat.set(8, 8);
        return texture;
    }

    static createInvaderGeometry(typeIndex) {
        // Create different geometries based on typeIndex (0-3 for different invader types)
        let geometry;

        if (typeIndex === 0) {
            // Squid-like shape
            const group = new THREE.Group();

            const bodyGeo = new THREE.BoxGeometry(0.8, 0.6, 0.4);
            const headGeo = new THREE.SphereGeometry(0.3, 8, 8);
            headGeo.scale(1, 0.7, 1);

            const material = new THREE.MeshStandardMaterial({ color: 0xff00ff });

            const body = new THREE.Mesh(bodyGeo, material);
            const head = new THREE.Mesh(headGeo, material);
            head.position.y = 0.5;

            group.add(body);
            group.add(head);

            // Convert group to merged geometry for InstancedMesh compatibility
