            geometry = new THREE.BoxGeometry(0.8, 0.6, 0.4);
        } else if (typeIndex === 1) {
            // Crab-like shape
            geometry = new THREE.ConeGeometry(0.5, 0.8, 4);
        } else if (typeIndex === 2) {
            // Octopus-like shape
            geometry = new THREE.DodecahedronGeometry(0.6);
        } else {
            // UFO shape for bonus
            geometry = new THREE.CylinderGeometry(0.8, 1.0, 0.3, 16);
        }

        return geometry;
