// shared/input/InputController.js
export class InputController {
    constructor() {
        this.keys = {
            left: false,
            right: false,
            fire: false
        };

        this.gamepadIndex = -1;

        window.addEventListener('keydown', (e) => this.handleKeyDown(e));
        window.addEventListener('keyup', (e) => this.handleKeyUp(e));
        window.addEventListener('gamepadconnected', (e) => this.handleGamepadConnect(e));
        window.addEventListener('gamepaddisconnected', (e) => this.handleGamepadDisconnect(e));
    }

    handleKeyDown(event) {
        switch(event.code) {
            case 'ArrowLeft':
            case 'KeyA':
                this.keys.left = true;
                break;
            case 'ArrowRight':
            case 'KeyD':
                this.keys.right = true;
                break;
            case 'Space':
            case 'Enter':
                this.keys.fire = true;
                break;
        }
    }

    handleKeyUp(event) {
        switch(event.code) {
            case 'ArrowLeft':
            case 'KeyA':
                this.keys.left = false;
                break;
            case 'ArrowRight':
            case 'KeyD':
                this.keys.right = false;
                break;
            case 'Space':
            case 'Enter':
                this.keys.fire = false;
                break;
        }
    }

    handleGamepadConnect(event) {
        const gamepad = navigator.gamepads[event.gamepad.index];
        if (gamepad && gamepad.mapping === 'standard' || gamepad.axes.length >= 2) {
            this.gamepadIndex = event.gamepad.index;
        }
    }

    handleGamepadDisconnect(event) {
        if (this.gamepadIndex === event.gamepad.index) {
            this.gamepadIndex = -1;
        }
    }

    getDirectionX() {
        let direction = 0;

        // Keyboard input
        if (this.keys.left) direction -= 1;
        if (this.keys.right) direction += 1;

        // Gamepad input
        if (this.gamepadIndex !== -1) {
            const gamepad = navigator.gamepads[this.gamepadIndex];
            if (gamepad && gamepad.axes.length >= 2) {
                const axisX = gamepad.axes[0];
                if (Math.abs(axisX) > 0.3) {
                    direction = Math.sign(axisX);
                }
            }
        }

        return direction;
    }

    isFirePressed() {
        if (this.keys.fire) return true;

        if (this.gamepadIndex !== -1) {
            const gamepad = navigator.gamepads[this.gamepadIndex];
            if (gamepad && gamepad.buttons.length > 0) {
                // Typically button 0 or 9 is the fire/shoot button
                if (gamepad.buttons[0] && gamepad.buttons[0].pressed) return true;
                if (gamepad.buttons[9] && gamepad.buttons[9].pressed) return true;
            }
        }

        return false;
    }

    isFireReleased() {
        return !this.keys.fire && this.gamepadIndex === -1;
    }
}
