        this.scene = scene;
        this.rings = [];
    }

    createShockwave(position, color = 0x00ffff) {
        const geometry = new THREE.RingGeometry(0.1, 0.2, 32);
        const material = new THREE.MeshBasicMaterial({
            color: color,
            transparent: true,
            opacity: 0.8,
            side: THREE.DoubleSide,
            depthWrite: false
        });

        const mesh = new THREE.Mesh(geometry, material);
        mesh.position.copy(position);
        mesh.rotation.x = -Math.PI / 2; // Flat on XZ plane
        this.scene.add(mesh);

        const ring = {
            mesh: mesh,
            startTime: performance.now(),
            duration: 1.0, // 1 second animation
            color: color
        };

        this.rings.push(ring);
    }

    update(deltaTime) {
        const currentTime = performance.now();

        for (let i = this.rings.length - 1; i >= 0; i--) {
            const ring = this.rings[i];
            const elapsed = (currentTime - ring.startTime) / 1000; // in seconds

            if (elapsed >= ring.duration) {
                // Remove ring
                if (ring.mesh.parent) {
                    ring.mesh.parent.remove(ring.mesh);
                }
                ring.mesh.geometry.dispose();
                ring.mesh.material.dispose();
                this.rings.splice(i, 1);
            } else {
                // Update scale and opacity
                const progress = elapsed / ring.duration;
                const scale = 1 + progress * 15; // Expand to 15x size
                ring.mesh.scale.set(scale, scale, 1);

                const opacity = Math.max(0, 0.8 * (1 - progress));
                ring.mesh.material.opacity = opacity;
            }
        }
    }

    dispose() {
        for (let ring of this.rings) {
            if (ring.mesh.parent) {
                ring.mesh.parent.remove(ring.mesh);
            }
            ring.mesh.geometry.dispose();
            ring.mesh.material.dispose();
        }
        this.rings = [];
    }
